 std::vector<Configuration> locals{one,two};auto localPlan=quality;localPlan.variables={{VariableParameter::Radius,0,45,55,1}};optimizeConfigurations(local,locals,localPlan);near(locals[0].values[0].value,0,1e-9,"First local focus reaches its independent optimum");near(locals[1].values[0].value,0,1e-9,"Second local focus is not overwritten by first");
 for(auto p:{DesignParameter::Radius,DesignParameter::Thickness,DesignParameter::Conic,DesignParameter::A4,DesignParameter::A6,DesignParameter::A8,DesignParameter::A10,DesignParameter::Defocus,DesignParameter::DecenterX,DesignParameter::DecenterY,DesignParameter::DecenterZ,DesignParameter::TiltX,DesignParameter::TiltY,DesignParameter::TiltZ,DesignParameter::IndexOffset,DesignParameter::RotationRadius,DesignParameter::Curvature}){
  auto v=base;DesignTarget t{p,0};const double value=designValue(v.system,v.catalog,t);setDesignValue(v.system,v.catalog,t,value+.001);near(designValue(v.system,v.catalog,t),value+.001,1e-10,"Every manufacturing target changes the intended stored quantity");}
 auto shifted=base;const double nd=base.catalog.get("N-BK7").index(.5875618);setDesignValue(shifted.system,shifted.catalog,{DesignParameter::IndexOffset,0},.0002);
 for(double w:{.4861327,.5875618,.6562725})near(shifted.catalog.get(shifted.system.surfaces[0].material).index(w)-base.catalog.get("N-BK7").index(w),.0002,1e-12,"Delta n adds to real dispersion at every wavelength");near(base.catalog.get("N-BK7").index(.5875618),nd,1e-12,"Index tolerance never mutates shared catalog glass");
 TolerancePlan plan;plan.operands={{{DesignParameter::Thickness,0},1,0,ToleranceDistribution::Uniform}};plan.samples=1000;plan.limit=.25;
 const auto draws=toleranceDraws(plan,10000);const auto again=toleranceDraws(plan,10000);check(draws==again,"Seed repeats the exact random realization within the same build");double mean=0,moment=0;bool bounded=true;for(auto row:draws){bounded&=std::abs(row[0])<=1;mean+=row[0];moment+=row[0]*row[0];}check(bounded,"Uniform errors stay within specified half width");near(mean/10000,0,.03,"Uniform empirical mean matches analytic zero");near(moment/10000,1./3,.02,"Uniform second moment matches analytic a squared / 3");
 plan.operands.push_back({{DesignParameter::Thickness,1},3,0,ToleranceDistribution::Normal});plan.correlation={{1,-1},{-1,1}};auto correlated=toleranceDraws(plan,1000);double covariance=0;for(auto row:correlated)covariance+=row[0]*row[1];check(covariance<-.4,"Gaussian copula preserves requested negative dependence across distributions");
 auto normalPlan=plan;normalPlan.operands[0].distribution=ToleranceDistribution::Normal;normalPlan.operands[0].amplitude=3;normalPlan.correlation={{1,.7},{.7,1}};auto normals=toleranceDraws(normalPlan,10000);double mx=0,my=0,vx=0,vy=0,cov=0;for(const auto& row:normals){mx+=row[0];my+=row[1];vx+=row[0]*row[0];vy+=row[1]*row[1];cov+=row[0]*row[1];}near(mx/10000,0,.04,"Correlated Gaussian first mean matches theory");near(my/10000,0,.04,"Correlated Gaussian second mean matches theory");near(vx/10000,1,.06,"Gaussian scale a=3 gives unit variance");near(vy/10000,1,.06,"Correlated Gaussian keeps specified marginal variance");near(cov/10000,.7,.06,"Cholesky samples reproduce specified normal covariance");
 plan.correlation={{1,.5},{-.5,1}};rejects([&]{toleranceDraws(plan,2);},"Asymmetric correlation is rejected");plan.correlation={{1,2},{2,1}};rejects([&]{toleranceDraws(plan,2);},"Impossible correlation is rejected");
 plan.operands.resize(1);plan.correlation.clear();auto report=runTolerances(base,{},quality,plan);near(report.after.fraction,.25,.06,"Uniform thickness yield matches independent analytic acceptance probability");check(report.after.total==1000&&report.convergence.back().total==1000,"Yield denominator includes every requested Monte Carlo trial");
 plan.compensators={{{DesignParameter::Defocus,0},-.5,.5,.25}};plan.compensationIterations=18;report=runTolerances(base,{},quality,plan);near(report.after.fraction,.75,.06,"Bounded compensation yield matches analytic 75 percent probability");check(report.after.fraction>report.before.fraction+.35,"Compensator materially improves yield");
 bool within=true,improved=true;for(const auto& sample:report.samples){within&=sample.corrections[0]>=-.5&&sample.corrections[0]<=.5;if(sample.after&&sample.before)improved&=*sample.after<=*sample.before+1e-10;}check(within,"Compensation obeys mechanical range");check(improved,"Compensation never worsens valid starting merit");
 const auto saved=toleranceRealization(base,{},plan,report.samples[0]);near(saved.system.imageZ()-base.system.imageZ(),report.samples[0].deltas[0]+report.samples[0].corrections[0],1e-10,"Saved realization includes actual perturbation and bounded correction");
 auto zero=wilsonYield(0,10),full=wilsonYield(10,10);near(zero.lower,0,1e-12,"Wilson interval has correct zero lower bound");near(zero.upper,.2775327999,1e-9,"Wilson zero-of-ten upper bound matches independent reference");near(full.lower,1-zero.upper,1e-12,"Wilson intervals are symmetric under success/failure exchange");
 plan.operands[0].mean=-10;plan.operands[0].amplitude=0;plan.samples=3;plan.compensators.clear();auto invalid=runTolerances(base,{},quality,plan);check(invalid.after.accepted==0&&invalid.after.total==3&&!invalid.samples[0].after,"Invalid geometry counts as failure rather than disappearing from yield");
 auto linkedPlan=plan;linkedPlan.operands={{{DesignParameter::Radius,1},0,1,ToleranceDistribution::Uniform}};ToleranceSample error;error.deltas={1};auto realization=toleranceRealization(linked,{},linkedPlan,error,false);near(realization.system.surfaces[1].radius,-49,1e-12,"Manufacturing deviation survives pickup by acting on resolved geometry");check(realization.system.solves.empty(),"Manufactured realization contains no nominal solve that could erase error");
 plan.operands[0].mean=0;plan.samples=20;calls=0;auto interrupted=runTolerances(base,{},quality,plan,[&](size_t,size_t,double){return ++calls<8;});check(interrupted.cancelled,"Monte Carlo can be cancelled inside its work");

 Surface free;free.profile=SurfaceProfile::XYPolynomial;free.radius=0;free.semiDiameter=4;free.xySag={.01,.002,.03,.004,-.003,.002,-.001};
 const double x=.4,y=-.3;const double z=.01*x*x+.002*x*y+.03*y*y+.004*x*x*x-.003*x*x*y+.002*x*y*y-.001*y*y*y;
 near(sag(free,x,y),z,1e-14,"Cartesian freeform sag matches independent polynomial evaluation");const auto normal=surfaceNormal(free,x,y);near(-normal.x/normal.z,.02*x+.002*y+.012*x*x-.006*x*y+.002*y*y,1e-12,"Freeform analytic X derivative matches expanded formula");
 const Vec3 point{x,y,z},direction=Vec3{.1,.2,1}.unit();auto hit=intersectSurface(free,{}, {point-direction*10,direction,.55});check(bool(hit),"Cubic freeform has a known constructed oblique ray intersection");near((hit->point-point).norm(),0,1e-7,"Freeform intersection recovers constructed surface point");
 free.xySag={0,0,0,1,0,0,0};auto nearest=intersectSurface(free,{},{{-2,0,-2},Vec3{1,0,1}.unit(),.55});check(bool(nearest),"Cubic ray crossing finds multiple real roots");near(nearest->point.x,-1,1e-7,"Cubic freeform selects nearest of three real intersections");
 free.xySag={1,0,0,0,0,0,0};auto tangent=intersectSurface(free,{},{{-1,0,0},{1,0,0},.55});check(bool(tangent),"Freeform retains repeated tangent root");near(tangent->point.x,0,1e-6,"Freeform tangent contact lies at known vertex");
 near(base.system.surfaces[0].radius,original.system.surfaces[0].radius,1e-12,"All studies leave base prescription unchanged unless explicitly optimizing");return n;
